    tan_donuts = image_patch.find("tan donut")
    white_donuts = image_patch.find("white donut")

    if not tan_donuts or not white_donuts:
        return image_patch

    tan_donut_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in tan_donuts]
    white_donut_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in white_donuts]

    for tan_donut, tan_center in zip(tan_donuts, tan_donut_centers):
        for white_donut, white_center in zip(white_donuts, white_donut_centers):
            if abs(tan_center[0] - white_center[0]) < abs(tan_center[1] - white_center[1]):
                return tan_donut
            else:
                return white_donut

